// Command pygen writes the generated Python code of the backend client package: the code
// classes, the retry advice, the models, the operations and the methods in
// calyx_client_sdk/_generated. With -core, it writes the one of the core client package: the
// models, the converters and the methods in calyx_client_sdk_core/_generated. Then it needs protoc.
//
// Run it from the tools folder. With -check, it compares the generated files with the files
// in -out, writes nothing, and exits with 1 on any difference.
package main

import (
	"flag"
	"fmt"
	"io"
	"os"
	"path/filepath"

	"calyx/sdktools/internal/genfiles"
	"calyx/sdktools/internal/protospec"
	"calyx/sdktools/internal/spec"
)

type paths struct {
	advice      string
	openAPI     string
	createCalls string
	out         string
	proto       string
	coreOut     string
}

// inputPaths returns the default inputs and output folders, relative to the tools folder.
func inputPaths(toolsDir string) paths {
	return paths{
		advice:      filepath.Join(toolsDir, "../testdata/retry-advice.json"),
		openAPI:     filepath.Join(toolsDir, "../../shared-types/openapi/backend.json"),
		createCalls: filepath.Join(toolsDir, "../testdata/create-calls.json"),
		out:         filepath.Join(toolsDir, "../python/backend/src/calyx_client_sdk/_generated"),
		proto:       filepath.Join(toolsDir, "../../shared-types/proto"),
		coreOut:     filepath.Join(toolsDir, "../python/core/src/calyx_client_sdk_core/_generated"),
	}
}

func main() {
	os.Exit(run(os.Args[1:], os.Stderr))
}

// run returns the exit code: 0 for success, 1 for a difference in -check mode, 2 for an error.
func run(args []string, out io.Writer) int {
	def := inputPaths(".")
	flags := flag.NewFlagSet("pygen", flag.ContinueOnError)
	flags.SetOutput(out)
	openAPI := flags.String("openapi", def.openAPI, "the OpenAPI document of the backend")
	advice := flags.String("advice", def.advice, "the retry advice of every code")
	createCalls := flags.String("create-calls", def.createCalls, "the retry advice of the create calls")
	protoDir := flags.String("proto", def.proto, "the folder of the .proto files of the core")
	core := flags.Bool("core", false, "write the files of the core package")
	outDir := flags.String("out", "", "the folder of the generated Python files (default: the one of the package)")
	check := flags.Bool("check", false, "compare the generated files with -out, write nothing there")
	if err := flags.Parse(args); err != nil {
		return 2
	}
	p := paths{advice: *advice, openAPI: *openAPI, createCalls: *createCalls, out: def.out, proto: *protoDir}
	if *core {
		p.out = def.coreOut
	}
	if *outDir != "" {
		p.out = *outDir
	}
	stale, err := generate(p, *core, *check)
	if err != nil {
		fmt.Fprintln(out, "pygen:", err)
		return 2
	}
	for _, name := range stale {
		fmt.Fprintf(out, "pygen: %s is out of date; run pnpm --filter @calyx/client-sdk-python generate\n", filepath.Join(p.out, name))
	}
	if len(stale) > 0 {
		return 1
	}
	return 0
}

// generate writes the files. With check, it writes nothing and returns the names of the files
// that are out of date.
func generate(p paths, core, check bool) ([]string, error) {
	files, err := newFiles(p, core)
	if err != nil {
		return nil, err
	}
	if check {
		return genfiles.Compare(files, p.out, ".py")
	}
	return nil, genfiles.Write(files, p.out, ".py")
}

func newFiles(p paths, core bool) (map[string][]byte, error) {
	if core {
		data, err := descriptorSet(p.proto)
		if err != nil {
			return nil, err
		}
		s, err := protospec.Parse(data, corePackage)
		if err != nil {
			return nil, err
		}
		return buildCoreFiles(s)
	}
	doc, err := spec.Load(p.openAPI, p.advice, p.createCalls)
	if err != nil {
		return nil, err
	}
	return buildFiles(doc)
}

const header = "# Code generated by pygen. DO NOT EDIT.\n"

// buildFiles returns the generated files by their path in the output folder.
func buildFiles(doc *spec.Doc) (map[string][]byte, error) {
	if err := checkCodes(doc.Advice); err != nil {
		return nil, err
	}
	w := newModelWriter(doc)
	models, err := w.file()
	if err != nil {
		return nil, err
	}
	methods, err := newMethods(w)
	if err != nil {
		return nil, err
	}
	return map[string][]byte{
		"__init__.py":   []byte(header),
		"codes.py":      codesFile(doc.Advice),
		"advice.py":     adviceFile(doc.Advice),
		"models.py":     models,
		"operations.py": operationsFile(methods),
		"methods.py":    methodsFile(methods),
	}, nil
}
